    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5, 6]), fmt([1, 1]), fmt([1000, 1000]), fmt([2, 3, 4, 5]), fmt([1, 1, 1, 1]), fmt([1000, 1, 1, 1000])]
    for n in (2, 4, 6, 8, 10, 12):
        for _ in range(3):
            tests.append(fmt([rng.randint(1, 20) for _ in range(n)]))
    for n in (6, 10, 12):
        tests.append(fmt([rng.randint(1, 1000) for _ in range(n)]))
    tests.append(fmt([rng.randint(100, 999) for _ in range(100)]))
    tests.append(fmt([rng.randint(100, 999) for _ in range(100)]))
    tests.append(fmt([1000] * 100))
    tests.append(fmt([rng.choice([100, 1000]) for _ in range(100)]))
    tests.append(fmt([100 + (i * 7) % 900 for i in range(100)]))
    return tests

